-- 20_seed_banks.sql  (generated from Policy_details_as_per_2024.xlsx)
-- Run AFTER 10_bank_policy_schema.sql. Safe to re-run: every insert upserts.
begin;

-- 1. Banks / NBFCs -------------------------------------------------
on conflict (slug) do update set name = excluded.name;

-- 2. Desks / contacts (one row per column of the sheet) ------------
on conflict (slug) do update set contact_name = excluded.contact_name, contact_phone = excluded.contact_phone, source_label = excluded.source_label;

-- 3. Policy criteria (one row per row of the sheet) ----------------
on conflict (slug) do update set sl_no = excluded.sl_no, label = excluded.label;

-- 4. The policy text itself (669 cells) --------------------
on conflict (desk_id, criterion_id) do update set policy_text = excluded.policy_text, updated_at = now();

-- 5. Machine-readable rules, auto-extracted from the text above ----
--    REVIEW THESE. Anything the parser could not read is null, which
--    means 'no hard filter' — the AI layer still sees the full text.
on conflict (desk_id) do update set min_salary_listed = excluded.min_salary_listed, min_salary_unlisted = excluded.min_salary_unlisted, min_cibil = excluded.min_cibil, min_age = excluded.min_age, max_age = excluded.max_age, min_exp_months = excluded.min_exp_months, max_loan_amount = excluded.max_loan_amount, max_tenure_months = excluded.max_tenure_months, max_foir_pct = excluded.max_foir_pct, roi_min = excluded.roi_min, roi_max = excluded.roi_max, unlisted_allowed = excluded.unlisted_allowed, contract_emp_allowed = excluded.contract_emp_allowed, bpo_nbfc_allowed = excluded.bpo_nbfc_allowed, has_policy_data = excluded.has_policy_data, updated_at = now();

commit;
